mapper.select:
SELECT t.transaction_id AS transactionId, t.parent_transaction_id AS parentTransactionId, t.user_id AS userId, t.receive_id AS receiveId, t.transaction_type AS transactionType, t.source_type AS sourceType, t.target_type AS targetType, t.transaction_status AS transactionStatus, t.amount, t.spending_category_id AS spendingCategoryId, t.created_at AS createdAt, m.memo_content AS memo, u.user_name AS receiverName FROM financial_transaction_tbl t LEFT JOIN receipt_memo_tbl m ON t.transaction_id = m.transaction_id LEFT JOIN user_tbl u ON t.receive_id = u.user_id WHERE t.user_id = #{userId}
AND t.transaction_type = #{type}
ORDER BY t.transaction_id DESC

mapper.update:
UPDATE receipt_memo_tbl
SET memo_content = #{memo}, updated_at = NOW()
WHERE transaction_id = #{transactionId}
